//! TLS against the test server: its certificate names only `localhost` and is
//! signed by a throwaway CA generated by `scripts/test-pg-certs.sh`.
use std::io;
use std::path::PathBuf;
use std::sync::Arc;

use crate::support::{TestResult, config};
use openrows_driver_api::DriverError;
use openrows_driver_postgres::{
    ConnectOptions, ConnectStage, ConnectTrace, PgConfig, PgSession, SslMode, TlsFiles, TlsStatus,
};
use openrows_net::testing::{TestProxy, TestProxyConfig};
use openrows_net::tls::{TlsDetails, Verification};
use openrows_net::{BoxFuture, BoxStream, Dialer, ProxyDialer, ProxyKind};

fn tls_file(name: &str) -> TestResult<PathBuf> {
    let dir = std::env::var("OPENROWS_TEST_PG_TLS_DIR")
        .map_err(|_| "OPENROWS_TEST_PG_TLS_DIR is unset: run with `just test-pg`")?;
    Ok(PathBuf::from(dir).join(name))
}

/// The test server under the only name its certificate is valid for.
fn localhost() -> TestResult<PgConfig> {
    Ok(PgConfig {
        host: "localhost".to_owned(),
        ..config()?
    })
}

fn with_ca(mode: SslMode, ca: &str) -> TestResult<ConnectOptions> {
    Ok(ConnectOptions {
        ssl_mode: mode,
        tls: TlsFiles {
            ca_file: Some(tls_file(ca)?),
            ..TlsFiles::default()
        },
        ..ConnectOptions::default()
    })
}

async fn connect(
    config: &PgConfig,
    options: &ConnectOptions,
) -> (Result<PgSession, DriverError>, ConnectTrace) {
    PgSession::connect_traced(config, options).await
}

fn encrypted(session: &PgSession) -> TestResult<TlsDetails> {
    match &session.server_info().tls {
        TlsStatus::Encrypted(details) => Ok(details.clone()),
        other => Err(format!("expected TLS, got {other:?}").into()),
    }
}

fn tls_message(result: Result<PgSession, DriverError>) -> TestResult<String> {
    match result {
        Err(DriverError::Tls(message)) => Ok(message),
        Err(other) => Err(format!("expected a TLS error, got {other}").into()),
        Ok(_) => Err("expected a TLS error, but the connection succeeded".into()),
    }
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn verify_full_with_the_ca_reports_every_stage_and_the_certificate() -> TestResult {
    let (session, trace) = connect(&localhost()?, &with_ca(SslMode::VerifyFull, "ca.crt")?).await;
    let details = encrypted(&session?)?;
    assert!(
        details.protocol.starts_with("TLS 1."),
        "{}",
        details.protocol
    );
    assert!(!details.cipher.is_empty());
    assert_eq!(details.subject.as_deref(), Some("CN=localhost"));
    assert_eq!(details.issuer.as_deref(), Some("CN=OpenRows Test CA"));
    assert_eq!(details.verification, Verification::Full);
    let stages: Vec<ConnectStage> = trace.completed.iter().map(|(stage, _)| *stage).collect();
    assert_eq!(
        stages,
        [
            ConnectStage::Resolve,
            ConnectStage::Connect,
            ConnectStage::Tls,
            ConnectStage::Authenticate,
            ConnectStage::ServerInfo,
            ConnectStage::StartupCommands
        ]
    );
    assert_eq!(trace.failed, None);
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn verify_full_rejects_a_name_the_certificate_does_not_cover() -> TestResult {
    let (result, trace) = connect(&config()?, &with_ca(SslMode::VerifyFull, "ca.crt")?).await;
    let message = tls_message(result)?;
    assert!(
        message.contains("not valid for this host name"),
        "{message}"
    );
    assert_eq!(trace.failed, Some(ConnectStage::Tls));
    let (chain_only, _) = connect(&config()?, &with_ca(SslMode::VerifyCa, "ca.crt")?).await;
    assert_eq!(encrypted(&chain_only?)?.verification, Verification::Chain);
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn untrusted_certificates_are_typed_tls_errors() -> TestResult {
    let (other_ca, _) = connect(
        &localhost()?,
        &with_ca(SslMode::VerifyFull, "other-ca.crt")?,
    )
    .await;
    let message = tls_message(other_ca)?;
    assert!(message.contains("not signed by a trusted CA"), "{message}");
    let system = ConnectOptions {
        ssl_mode: SslMode::VerifyFull,
        ..ConnectOptions::default()
    };
    let (system_store, trace) = connect(&localhost()?, &system).await;
    tls_message(system_store)?;
    assert_eq!(trace.failed, Some(ConnectStage::Tls));
    let missing = ConnectOptions {
        ssl_mode: SslMode::VerifyCa,
        ..ConnectOptions::default()
    };
    let message = tls_message(connect(&localhost()?, &missing).await.0)?;
    assert!(message.contains("CA certificate file"), "{message}");
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn require_and_prefer_encrypt_without_verification() -> TestResult {
    for mode in [SslMode::Require, SslMode::Prefer] {
        let options = ConnectOptions {
            ssl_mode: mode,
            ..ConnectOptions::default()
        };
        let (session, _) = connect(&config()?, &options).await;
        assert_eq!(
            encrypted(&session?)?.verification,
            Verification::None,
            "{mode:?}"
        );
    }
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn client_certificates_log_in_cert_authenticated_roles() -> TestResult {
    let certuser = PgConfig {
        user: "certuser".to_owned(),
        password: None,
        ..localhost()?
    };
    let mut options = with_ca(SslMode::VerifyFull, "ca.crt")?;
    let (anonymous, _) = connect(&certuser, &options).await;
    assert!(
        matches!(
            anonymous,
            Err(DriverError::Auth(_) | DriverError::Server { .. })
        ),
        "certificate authentication needs a client certificate"
    );
    options.tls.client_cert = Some(tls_file("client.crt")?);
    options.tls.client_key = Some(tls_file("client.key")?);
    let (session, _) = connect(&certuser, &options).await;
    assert_eq!(session?.server_info().user, "certuser");
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn allow_retries_with_tls_when_plaintext_is_rejected() -> TestResult {
    let tls_only = PgConfig {
        user: "tlsonly".to_owned(),
        ..config()?
    };
    let options = ConnectOptions {
        ssl_mode: SslMode::Allow,
        ..ConnectOptions::default()
    };
    let (session, trace) = connect(&tls_only, &options).await;
    encrypted(&session?)?;
    assert!(trace.retried_with_tls);
    let disable = ConnectOptions {
        ssl_mode: SslMode::Disable,
        ..ConnectOptions::default()
    };
    let (rejected, _) = connect(&tls_only, &disable).await;
    assert!(rejected.is_err(), "the role may not connect in plaintext");
    Ok(())
}

/// Dials the test server directly, standing in for an SSH tunnel.
struct LoopbackDialer(u16);

impl Dialer for LoopbackDialer {
    fn dial(&self) -> BoxFuture<'_, io::Result<BoxStream>> {
        Box::pin(async move {
            let stream = tokio::net::TcpStream::connect(("127.0.0.1", self.0)).await?;
            let stream: BoxStream = Box::new(stream);
            Ok(stream)
        })
    }

    fn describe(&self) -> String {
        format!("loopback:{}", self.0)
    }
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn routed_streams_verify_tls_against_the_configured_host() -> TestResult {
    let server = config()?;
    let routed = PgConfig {
        host: "localhost".to_owned(),
        port: 1,
        ..server.clone()
    };
    let options = ConnectOptions {
        via: Some(Arc::new(LoopbackDialer(server.port))),
        ..with_ca(SslMode::VerifyFull, "ca.crt")?
    };
    let (session, _) = connect(&routed, &options).await;
    assert_eq!(
        encrypted(&session?)?.subject.as_deref(),
        Some("CN=localhost")
    );
    Ok(())
}

#[tokio::test]
#[ignore = "needs PostgreSQL: run `just test-pg`"]
async fn proxies_carry_verified_tls_sessions_and_resolve_names_remotely() -> TestResult {
    let server = localhost()?;
    for kind in [ProxyKind::Socks5, ProxyKind::HttpConnect] {
        let proxy = TestProxy::start(TestProxyConfig {
            kind,
            credentials: Some(("ops".to_owned(), "proxy-pw-synthetic".to_owned())),
        })
        .await?;
        let dialer = ProxyDialer::new(Arc::new(proxy.spec()), "localhost", server.port);
        let options = ConnectOptions {
            via: Some(Arc::new(dialer)),
            ..with_ca(SslMode::VerifyFull, "ca.crt")?
        };
        let (session, trace) = connect(&server, &options).await;
        let details = encrypted(&session?)?;
        assert_eq!(details.subject.as_deref(), Some("CN=localhost"));
        assert_eq!(details.alt_names, ["localhost"]);
        assert!(
            trace
                .completed
                .iter()
                .any(|(stage, _)| *stage == ConnectStage::Tls)
        );
        assert_eq!(
            proxy.destinations(),
            [format!("localhost:{}", server.port)],
            "{kind}: the proxy resolves the host name"
        );
    }
    Ok(())
}
